def recevoir(stock, article, quantite):
    if quantite <= 0:
        return None
    copie = stock.copy()
    copie[article] = copie.get(article, 0) + quantite
    return copie

def total_prevu(stock, quantite):
    total = quantite
    for code in stock:
        total = total + stock[code]
    return total

def recevoir_lot(stock, livraisons):
    copie = stock.copy()
    for article, quantite in livraisons:
        copie[article] = copie.get(article, 0) + quantite
    return copie
